import sys

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    n = int(input_data[0])
    b = input_data[1]

    count = 0
    i = 0
    while i < n - 2:
        if b[i] == '0' and b[i+1] == '1' and b[i+2] == '0':
            count += 1
            i += 3
        else:
            i += 1

    print(count)

if __name__ == "__main__":
    main()
